mapper.select:
SELECT v.VALUATION_ID as "valuationId", v.INVENTORY_ID as "inventoryId", v.INVENTORY_CODE as "inventoryCode", v.INVENTORY_NAME as "inventoryName", v.WAREHOUSE_ID as "warehouseId", COALESCE(v.WAREHOUSE_NAME, m.WAREHOUSE_NAME) as "warehouseName", m.CATEGORY_ID as "categoryId", m.CATEGORY_NAME as "categoryName", v.PRICING_METHOD as "pricingMethod", CASE v.PRICING_METHOD WHEN 1 THEN '移动平均法' WHEN 2 THEN '先进先出法' WHEN 3 THEN '加权平均法' WHEN 4 THEN '个别计价法' ELSE '未知' END as "pricingMethodName", v.UNIT_COST as "unitCost", v.CURRENT_QUANTITY as "currentQuantity", v.TOTAL_VALUE as "totalValue", v.BEGINNING_QUANTITY as "beginningQuantity", v.BEGINNING_AMOUNT as "beginningAmount", v.IN_QUANTITY as "inQuantity", v.IN_AMOUNT as "inAmount", v.OUT_QUANTITY as "outQuantity", v.OUT_AMOUNT as "outAmount", v.VALUATION_PERIOD as "valuationPeriod", v.STATUS as "status", v.UPDATE_TIME as "updateTime" FROM TBL_INVENTORY_VALUATION v LEFT JOIN TBL_INVENTORY_MASTER m ON v.INVENTORY_ID = m.INVENTORY_ID AND m.DELETED = 0 WHERE v.TENANT_ID = #{param.tenantId}
AND v.INVENTORY_CODE LIKE '%' || #{param.inventoryCode} || '%'
AND v.INVENTORY_NAME LIKE '%' || #{param.inventoryName} || '%'
AND v.WAREHOUSE_ID = #{param.warehouseId}
AND v.PRICING_METHOD = #{param.pricingMethod}
AND v.STATUS = #{param.status}
AND v.VALUATION_PERIOD = #{param.valuationPeriod}
ORDER BY v.UPDATE_TIME DESC, v.VALUATION_ID DESC

SELECT * FROM TBL_INVENTORY_VALUATION
WHERE INVENTORY_ID = #{inventoryId}
AND TENANT_ID = #{tenantId}
ORDER BY UPDATE_TIME DESC
FETCH FIRST 1 ROWS ONLY

SELECT * FROM TBL_INVENTORY_VALUATION
WHERE INVENTORY_CODE = #{inventoryCode}
AND TENANT_ID = #{tenantId}
ORDER BY UPDATE_TIME DESC
FETCH FIRST 1 ROWS ONLY

SELECT * FROM TBL_INVENTORY_VALUATION
WHERE WAREHOUSE_ID = #{warehouseId}
AND TENANT_ID = #{tenantId}
ORDER BY UPDATE_TIME DESC

SELECT * FROM TBL_INVENTORY_VALUATION
WHERE PRICING_METHOD = #{pricingMethod}
AND TENANT_ID = #{tenantId}
ORDER BY UPDATE_TIME DESC

